/* The heavy half of the eg cards — GENERATED, never hand-edited.
 *
 * abstract / sources / why / quote / image, for the cards whose ids begin `eg-`. None of it is
 * read until a reader REVEALS a card in this collection, so it is fetched then (bundle
 * `cardExtra:eg`) rather than downloaded by every visitor before they can flip one.
 *
 * IT STAGES ONTO A QUEUE rather than assigning, for the reason glossary-extra.js does: app.js
 * snapshots PRISTINE_CARDS at boot, which is BEFORE this file lands, so a plain assignment would
 * leave the editor's revert baseline empty and Revert would DELETE a shipped abstract rather than
 * restore it. cardExtraIngest drains the queue and re-seeds that baseline.
 *
 * An id data.js does not carry is not resurrected — the light half decides what a card is. */
(function () {
  var CARD_EXTRA = {
    "eg-001": {"abstract":"<b>Kemet</b> was what Egyptians called their own country, and the word means the Black Land: it named the dark alluvial soil of the Nile valley, as against the reddish surface of the desert on either side, which they called the Red Land.<sup class=\"fn\" data-fn=\"1\"></sup> The pairing was not decorative, because for an Egyptian the world consisted of those two things, so that to go up was to leave the valley and to descend was the ordinary word for coming home from abroad.<sup class=\"fn\" data-fn=\"1\"></sup> The black soil is the river's doing, carried down from the Ethiopian highlands by the summer flood and dropped on the fields while the water stood on them.<sup class=\"fn\" data-fn=\"1\"></sup> Herodotus was told as much by Egyptian priests, and satisfied himself of it by sounding a day's sail off the coast and bringing up mud from eleven fathoms.<sup class=\"fn\" data-fn=\"2\"></sup> In the valley that deposit lies ten to twelve metres (33 to 38 feet) deep, and the cultivated strip it makes is at most sixteen kilometres (10 miles) wide.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Between the first cataract and the sea the whole of that strip came to under 26,000 square kilometres (10,000 square miles), which is roughly the area of Belgium.<sup class=\"fn\" data-fn=\"1\"></sup> Strabo turned the consequence into a definition, writing that Egypt consists of only the river-land on either side of the Nile.<sup class=\"fn\" data-fn=\"3\"></sup> What lay beyond was not worthless, since the eastern desert held gold-bearing quartz, alabaster and hard stone and the roads to the Red Sea harbours crossed it, but it fed only a few wandering people.<sup class=\"fn\" data-fn=\"1\"></sup> The Black Land has never been fixed in place either, and coring beside the pyramid field has traced a large Nile branch, long since dry, running along the foot of the western plateau where most of the pyramids stand.<sup class=\"fn\" data-fn=\"4\"></sup> An 8,000-year sediment budget for the delta shows the same restlessness, the plain growing through the early and middle Holocene and then losing ground from about 4,000 years ago as the flood weakened and people moved onto the land it left.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 4–11, https://archive.org/details/historyofegyptfr00brea. [Open access]","Herodotus, <i>The Histories</i> 2.5, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D2%3Achapter%3D5. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Eman Ghoneim, Timothy J. Ralph, Suzanne Onstine, Raghda El-Behaedi, Gad El-Qady, Amr S. Fahil, Mahfooz Hafez, Magdy Atya, Mohamed Ebrahim, Ashraf Khozym and Mohamed S. Fathy, “The Egyptian Pyramid Chain Was Built along the Now Abandoned Ahramat Nile Branch,” <i>Communications Earth & Environment</i> 5 (2024): 233, https://doi.org/10.1038/s43247-024-01379-7. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]"],"why":[{"q":"Why did Egyptians name their country after its soil rather than its river?","a":"Because the soil was what the river left them. The flood carried loam down from the Ethiopian highlands and dropped it on the fields while the water stood on them, so the black ground was the visible, farmable result of the river's work."},{"q":"Why was the boundary between the Black Land and the Red Land so sharp?","a":"Because cultivation stopped where the flood stopped. The alluvium is at most about sixteen kilometres wide, with desert plateau on either side of it, so the dark soil ended and the reddish desert surface began within a short distance."},{"q":"Why is calling the Black Land a fixed place misleading?","a":"Because the water that made it has moved. A large Nile branch that ran along the western plateau beside the pyramid field is now dry, and the delta grew for several thousand years and then began losing ground about 4,000 years ago."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Egypt_and_the_Nile_River_%28MODIS_2017-09-26%29.jpg/1920px-Egypt_and_the_Nile_River_%28MODIS_2017-09-26%29.jpg","title":"The Black Land from orbit","desc":"The cultivated strip along the Nile in southern Egypt, with Lake Nasser behind the Aswan dam and the Red Sea at the upper right. Everything pale is desert.","credit":"Jeff Schmaltz, MODIS Land Rapid Response Team, NASA GSFC, Public domain, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Egypt_and_the_Nile_River_(MODIS_2017-09-26).jpg","alt":"A satellite view of pale desert crossed by a narrow winding band of dark green following a river, with a long dark lake to the south and a deep blue sea at the right."}},
    "eg-002": {"abstract":"The <b>Nile</b> is the river of north-east Africa, and the one Egypt is built on: the White Nile out of the East African lakes and the Blue Nile out of the Ethiopian highlands meet at Khartoum, and the Atbara joins below them as the last tributary of all.<sup class=\"fn\" data-fn=\"1\"></sup> More than 97 per cent of Egypt's fresh water is Nile water, and over 85 per cent of that originates in the Ethiopian highlands and is carried down by the Blue Nile, the Sobat and the Atbara.<sup class=\"fn\" data-fn=\"2\"></sup> Below the Atbara the river crosses the eastern Sahara alone, cutting a trench through limestone that runs sixteen to fifty kilometres (10 to 31 miles) from cliff to cliff and flowing at about five kilometres an hour (3 miles an hour).<sup class=\"fn\" data-fn=\"3\"></sup> Strabo saw what that meant for the country beside it, writing that above the Delta the river runs some four thousand stadia in a single channel and the habitable ground is scarcely anywhere three hundred stadia broad.<sup class=\"fn\" data-fn=\"4\"></sup> The basin behind it covers about 2,900,000 square kilometres (1,120,000 square miles) between four degrees south and thirty two degrees north, though the deserts north of Berber contribute nothing.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> About 160 kilometres (100 miles) from the sea the stream opens into the triangle the Greeks named the Delta, where antiquity counted seven mouths and only two main branches now reach the coast, the Rosetta and the Damietta.<sup class=\"fn\" data-fn=\"3\"></sup> Between Khartoum and Aswan the water runs through a series of granite cataracts, and the first of these was Egypt's own southern frontier for most of its history.<sup class=\"fn\" data-fn=\"3\"></sup> The channels have never been fixed: radar imaging and soil coring beside the pyramid field have traced a major branch running along the foot of the Western Desert plateau that is now buried and dry.<sup class=\"fn\" data-fn=\"5\"></sup> Neither has the volume, and an 8,000-year sediment budget from the delta shows accretion falling away through the Holocene with erosion first recorded about 4,000 years ago.<sup class=\"fn\" data-fn=\"6\"></sup> A country with almost no rain and one river takes its whole arrangement from what that river is doing.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["H. G. Lyons, <i>The Physiography of the River Nile and Its Basin</i> (Cairo: Survey Department, 1906), 4–7, https://archive.org/details/physiographyriv00lyongoog. [Open access]","Karem Abdelmohsen, Mohamed Sultan, Eugene Yan, Abotalib Z. Abotalib, Himanshu Save, Mustafa Emil, Hesham Elhaddad and Karim Abdelmalik, “Watching the Grand Ethiopian Renaissance Dam from a Distance: Implications for Sustainable Water Management of the Nile Water,” <i>PNAS Nexus</i> 3, no. 7 (2024): pgae219, https://pmc.ncbi.nlm.nih.gov/articles/PMC11214100/. [Open access]","James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 4–8, https://archive.org/details/historyofegyptfr00brea. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Eman Ghoneim, Timothy J. Ralph, Suzanne Onstine, Raghda El-Behaedi, Gad El-Qady, Amr S. Fahil, Mahfooz Hafez, Magdy Atya, Mohamed Ebrahim, Ashraf Khozym and Mohamed S. Fathy, “The Egyptian Pyramid Chain Was Built along the Now Abandoned Ahramat Nile Branch,” <i>Communications Earth & Environment</i> 5 (2024): 233, https://doi.org/10.1038/s43247-024-01379-7. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]"],"why":[{"q":"Why does a drought in Ethiopia matter more to Egypt than one in Egypt?","a":"Because over 85 per cent of the water Egypt receives originates in the Ethiopian highlands and is carried down by the Blue Nile, the Sobat and the Atbara, while more than 97 per cent of Egypt's fresh water is Nile water in the first place."},{"q":"Why does the river gain nothing after the Atbara?","a":"Because from that junction it crosses the eastern Sahara, where nothing drains into it. Lyons noted that the deserts north of Berber contribute nothing to the flow at all, so the river only loses water between there and the sea."},{"q":"Why is it wrong to picture the Nile as a fixed line on the map?","a":"Because its channels have moved. Radar imaging and coring beside the pyramid field have found a major branch along the Western Desert plateau that is now dry and buried, and seven mouths once reached the sea where two main branches do now."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Egypt%E2%80%99s_Nile_River_stretches_from_Luxor_to_Cairo_%28iss073e0422271%29.jpg/1920px-Egypt%E2%80%99s_Nile_River_stretches_from_Luxor_to_Cairo_%28iss073e0422271%29.jpg","title":"The Nile at night","desc":"Lights along the river between Luxor and Cairo, photographed from the International Space Station in July 2025. The ground on either side is unlit desert.","credit":"NASA Johnson Space Center, Public domain, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Egypt%E2%80%99s_Nile_River_stretches_from_Luxor_to_Cairo_(iss073e0422271).jpg","alt":"A night photograph from orbit in which a thin ribbon of lights winds across otherwise black ground, widening into a bright cluster at one end."}},
    "eg-003": {"abstract":"The <b>inundation</b> was the Nile's annual summer flood, and until the twentieth century it was the one fact Egyptian farming was arranged around.<sup class=\"fn\" data-fn=\"1\"></sup> Its water was monsoon rain that had fallen on the Ethiopian highlands and come down the Blue Nile and the Atbara, so the flood reached Egypt out of weather Egypt never has.<sup class=\"fn\" data-fn=\"1\"></sup> Before the dams the rise was first seen at Aswan as early as June, peaked between August and September, and had largely receded by the end of October, when sowing began.<sup class=\"fn\" data-fn=\"1\"></sup> Near the first cataract the water stood about fifteen metres (50 feet) higher than at low water, and at Cairo roughly half that.<sup class=\"fn\" data-fn=\"2\"></sup> It was caught in basins behind dykes and let out onto the fields as it was wanted, and it lay there long enough to drop the silt that renewed the ground.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Strabo set out the timetable: the water stands on the plain more than forty days, goes down as gradually as it rose, and in sixty days the plain is bare and drying, with the ploughing and the sowing following the drying.<sup class=\"fn\" data-fn=\"3\"></sup> Herodotus asked priests and others why the river came down in flood for a hundred days from the summer solstice and then sank for the whole winter, and could get an answer from nobody.<sup class=\"fn\" data-fn=\"4\"></sup> What made the flood frightening was that it varied, and the Islamic nilometer readings, running from 622 to 1902 CE, are a long enough series to measure how much.<sup class=\"fn\" data-fn=\"1\"></sup> Explosive volcanic eruptions weakened the African monsoon and with it the flood, and in Ptolemaic Egypt eruption years coincide with the onset of revolt, the breaking off of foreign war and a rise in sales of hereditary land.<sup class=\"fn\" data-fn=\"1\"></sup> Twentieth-century damming ended the cycle, and the delta that the silt used to build is now a sediment-starved system with no direct parallel earlier in the Holocene.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Joseph G. Manning, Francis Ludlow, Alexander R. Stine, William R. Boos, Michael Sigl and Jennifer R. Marlon, “Volcanic Suppression of Nile Summer Flooding Triggers Revolt and Constrains Interstate Conflict in Ancient Egypt,” <i>Nature Communications</i> 8 (2017): 900, https://doi.org/10.1038/s41467-017-00957-y. [Open access]","James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 8–9, https://archive.org/details/historyofegyptfr00brea. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Herodotus, <i>The Histories</i> 2.19, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D2%3Achapter%3D19. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]"],"why":[{"q":"Why did the Nile flood in summer, when Egypt gets no summer rain?","a":"Because the water was not Egyptian rain. It was monsoon rainfall on the Ethiopian highlands, carried down by the Blue Nile and the Atbara, so the flood arrived in Egypt in a season that has no weather of its own there."},{"q":"Why did a volcanic eruption thousands of kilometres away matter to an Egyptian farmer?","a":"Because explosive eruptions weakened the African monsoon and so suppressed the flood. In Ptolemaic Egypt eruption years coincide with the onset of revolt, the breaking off of war with the Seleukids and a rise in sales of hereditary land."},{"q":"Why did the flood have to recede before the work of the year could start?","a":"Because the crop was sown into the drained ground. Strabo records the water standing more than forty days and the plain taking sixty to bare and dry, with ploughing and sowing following the drying, and sowing beginning as the water went in October."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Nilometer_Rhoda_Island_Cairo_Egypt_%282%29.jpg/1920px-Nilometer_Rhoda_Island_Cairo_Egypt_%282%29.jpg","title":"The Nilometer shaft on Rhoda Island","desc":"A graduated column standing in a stone well at Cairo, cut so that the height of the yearly flood could be read off it.","credit":"Radosław Botev, CC BY 3.0 pl, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Nilometer_Rhoda_Island_Cairo_Egypt_(2).jpg","alt":"Looking down into a deep square stone well with a tall octagonal column rising through the middle of it and pointed arched recesses in the walls."}},
    "eg-004": {"abstract":"The <b>Two Lands</b> is how Egyptians described their own country, as the narrow valley of the south and the delta of the north held together under one king rather than as a single place.<sup class=\"fn\" data-fn=\"1\"></sup> The doubling ran through everything the crown did: the palace was double, a Third Dynasty pharaoh built two tombs in his double capacity as king of the Two Lands, and each reign opened with a feast called the Union of the Two Lands.<sup class=\"fn\" data-fn=\"1\"></sup> The colour of the south was white, its crown tall and white, its emblem a southern plant and its treasury the White House, with its old capital at Nekheb and a royal residence at Nekhen across the river.<sup class=\"fn\" data-fn=\"1\"></sup> The colour of the north was red, with a red crown peculiar to it in both colour and shape, a tuft of papyrus for its badge, a bee for its king and a treasury called the Red House.<sup class=\"fn\" data-fn=\"1\"></sup> Each half had its own protecting goddess, the vulture Nekhbet in the south and the serpent goddess of Buto in the north, while the hawk-god Horus was the patron of both kings.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Behind those symbols Breasted's generation reconstructed two prehistoric kingdoms that had merged, and what the monuments themselves show is the doubling, carried by royal title and regalia for three thousand years.<sup class=\"fn\" data-fn=\"1\"></sup> The geography under it is real enough, because a valley whose cultivable floor is at most sixteen kilometres (10 miles) wide is a different country from a fan of branches beginning about 160 kilometres (100 miles) from the sea.<sup class=\"fn\" data-fn=\"2\"></sup> Greek writers used the same split, Herodotus reckoning Egypt from the Cataracts and Elephantine downwards and Strabo calling the Delta and the river-lands opposite it Lower Egypt.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> The delta is physically distinct too, an accreting plain whose growth and later erosion can be measured over 8,000 years as a sediment budget of its own.<sup class=\"fn\" data-fn=\"5\"></sup> What the two halves shared was the flood, which reached them in the same weeks of the year and which neither could do without.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 31–34, 47 and 71, https://archive.org/details/historyofegyptfr00brea. [Open access]","James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 5–6, https://archive.org/details/historyofegyptfr00brea. [Open access]","Herodotus, <i>The Histories</i> 2.17, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D2%3Achapter%3D17. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]","Joseph G. Manning, Francis Ludlow, Alexander R. Stine, William R. Boos, Michael Sigl and Jennifer R. Marlon, “Volcanic Suppression of Nile Summer Flooding Triggers Revolt and Constrains Interstate Conflict in Ancient Egypt,” <i>Nature Communications</i> 8 (2017): 900, https://doi.org/10.1038/s41467-017-00957-y. [Open access]"],"why":[{"q":"Why did a united Egypt keep two of everything?","a":"Because union was treated as the joining of two things rather than the making of one. The palace was double, a Third Dynasty king built two tombs in his double capacity, there were two treasuries, and each reign opened with a feast called the Union of the Two Lands."},{"q":"Why is the valley a different sort of country from the delta?","a":"Because their shapes are nothing alike. The valley's cultivable floor is at most about sixteen kilometres wide between desert cliffs, while the delta is a fan of branches spreading from about 160 kilometres inland to the coast."},{"q":"Why should the two prehistoric kingdoms be treated more carefully than the two crowns?","a":"Because they rest on different evidence. The crowns, colours, badges, treasuries and goddesses are on the monuments; the pair of kingdoms behind them is a reconstruction made from those symbols by an earlier generation of scholars."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Narmer_Palette.jpg/1920px-Narmer_Palette.jpg","title":"Both faces of the Narmer Palette","desc":"On the left the king wears the tall white crown of the south and on the right the red crown of the north, the two halves the Egyptians called the Two Lands.","credit":"anonymous, Public domain, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Narmer_Palette.jpg","alt":"Two views of a shield-shaped dark stone slab carved in low relief with a striding king, animals and rows of small figures."}},
    "eg-005": {"abstract":"The <b>Nile Delta</b> is the triangle of silt the river has built where it meets the Mediterranean, and it carries the name of the Greek letter whose shape it has.<sup class=\"fn\" data-fn=\"3\"></sup> Herodotus reckoned that the river ran in a single channel as far as Cercasorus and divided there into three, the Pelusian mouth flowing east, the Canobic west and the Sebennytic straight through the middle as the greatest of them.<sup class=\"fn\" data-fn=\"2\"></sup> Antiquity counted seven mouths in all, where two main branches now reach the coast, the Rosetta on the west and the Damietta on the east.<sup class=\"fn\" data-fn=\"1\"></sup> Strabo put the island itself at as much as three thousand stadia round and called it, together with the river-lands opposite, Lower Egypt.<sup class=\"fn\" data-fn=\"3\"></sup> He also described what the flood did to it, the whole country going under water and becoming a lake except for the settlements, which stood on natural hills or artificial mounds and from a distance resembled islands.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The deposits are very deep, and Breasted observed that the material remains of the delta's earliest civilisation are buried under Nile mud beyond anyone's reach.<sup class=\"fn\" data-fn=\"1\"></sup> An 8,000-year mass balance shows the plain growing through the early and middle Holocene while its accretion rates fell steadily away with the weakening monsoon.<sup class=\"fn\" data-fn=\"4\"></sup> Sediment losses and pronounced erosion first register after about 4,000 years ago, as the supply of silt fell and people spread onto the floodplain that the lower water exposed.<sup class=\"fn\" data-fn=\"4\"></sup> At the north-western edge the Mareotis lagoon records the same turn, fed mainly by the Nile between roughly 7,000 and 5,500 years ago and shifting towards a marine-dominated system as the African humid period ended.<sup class=\"fn\" data-fn=\"5\"></sup> The delta today is sediment-starved in a way with no direct parallel earlier in the Holocene, which is what makes its long record of exposure to floods, storms and rising sea level worth reading.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 5–6 and 31, https://archive.org/details/historyofegyptfr00brea. [Open access]","Herodotus, <i>The Histories</i> 2.17, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D2%3Achapter%3D17. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]","Clément Flaux, Matthieu Giaime, Valérie Pichot, Nick Marriner, Mena el-Assal, Abel Guihou, Pierre Deschamps, Christelle Claude and Christophe Morhange, “The Late Holocene Record of Lake Mareotis, Nile Delta, Egypt,” <i>E&G Quaternary Science Journal</i> 70, no. 1 (2021): 93–104, https://doi.org/10.5194/egqsj-70-93-2021. [Open access]"],"why":[{"q":"Why are the delta's earliest towns so much harder to find than the valley's?","a":"Because the river has gone on burying them. The deposits there are very deep and the material remains of the delta's earliest civilisation lie under Nile mud, where a valley cemetery sits on the dry desert margin instead."},{"q":"Why did the delta stop growing and start eroding?","a":"Because the silt supply fell. Accretion rates declined through the Holocene with the weakening monsoon, and after about 4,000 years ago sediment losses and pronounced erosion register for the first time."},{"q":"Why did settlement on the delta expand as the river weakened?","a":"Because lower water exposed productive floodplain that had been under it. The same decline in flow that starved the delta of sediment opened ground for occupation and for irrigation farming."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Nile_River_Delta_%28MODIS_2021-05-26%29.jpg/1920px-Nile_River_Delta_%28MODIS_2021-05-26%29.jpg","title":"The delta from orbit","desc":"The green fan of cultivated land spreading from the valley to the Mediterranean coast, with the Faiyum as a separate patch of green to the south-west and the Gulf of Suez at the right.","credit":"MO'DIS Land Rapid Response Team, NASA GSFC, Public domain, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Nile_River_Delta_(MODIS_2021-05-26).jpg","alt":"A satellite view of a broad green triangle of farmland meeting a dark blue sea, surrounded by pale desert, with a narrow green strip running south from its point."}},
    "eg-006": {"abstract":"The <b>Faiyum</b> is a large depression in the desert west of the Nile, close enough to the valley that the rock wall between them broke down, and a gap in the western hills about 105 kilometres (65 miles) above the southern apex of the Delta leads into it.<sup class=\"fn\" data-fn=\"1\"></sup> It is watered by the Bahr Yusuf, a second channel some 320 kilometres (200 miles) long that leaves the main stream near Asyut and runs down into the basin.<sup class=\"fn\" data-fn=\"1\"></sup> Breasted described it as shaped like a huge maple leaf roughly 65 kilometres (40 miles) across each way, its lowest ground in the north-west held by the lake now called Birket el-Qarun.<sup class=\"fn\" data-fn=\"1\"></sup> That lake covers about 238 square kilometres (92 square miles) today and has been badly degraded by the agricultural drainage emptied into it.<sup class=\"fn\" data-fn=\"5\"></sup> Herodotus was shown it as Lake Moeris and took it for a work of human hands, reporting a circumference of sixty schoeni, a channel that carried Nile water in for six months and out for six, and a royal fishery worth a silver talent a day.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Strabo called the Arsinoite nome the most noteworthy in Egypt for its appearance, its fertility and its development, the only one with large olive trees, and Moeris an open sea in size and sea-coloured.<sup class=\"fn\" data-fn=\"4\"></sup> Long before either writer the basin held some of the earliest settled life in the country, occupied from about 7350 BCE.<sup class=\"fn\" data-fn=\"2\"></sup> Domesticated plants and animals appear there from roughly 5400 BCE, part of a two-phase arrival in which the sixth millennium yields very little and the fifth a great deal more.<sup class=\"fn\" data-fn=\"2\"></sup> At the villages of Kom K and Kom W, dated between 4850 and 4250 BCE, fish still dominate the animal bones despite the presence of domesticates, in continuity with the earlier Holocene occupation.<sup class=\"fn\" data-fn=\"2\"></sup> The basin is therefore where farming in Egypt can be watched arriving slowly, alongside a fishery that went on feeding people throughout.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 5 and 191, https://archive.org/details/historyofegyptfr00brea. [Open access]","Veerle Linseele, Wim Van Neer, Sofie Thys, Rebecca Phillipps, René Cappers, Willeke Wendrich and Simon Holdaway, “New Archaeozoological Data from the Fayum ‘Neolithic’ with a Critical Assessment of the Evidence for Early Stock Keeping in Egypt,” <i>PLOS ONE</i> 9, no. 10 (2014): e108517, https://doi.org/10.1371/journal.pone.0108517. [Open access]","Herodotus, <i>The Histories</i> 2.149, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D2%3Achapter%3D149. [Open access]","Strabo, <i>Geography</i> 17.1.35, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A3*.html. [Open access]","Ahmed M. Khalifa, Khaled Z. ElBaghdady, Sayed Abdel-Karim, Sameh B. El Kafrawy, Elsayed M. Nafea and Ahmed M. El-Zeiny, “Geospatial Assessment of Heavy Metal Contamination and Metal-Resistant Bacteria in Qarun Lake, Egypt,” <i>Environmental Sciences Europe</i> 37 (2025): 62, https://doi.org/10.1186/s12302-025-01152-3. [Open access]"],"why":[{"q":"Why is there a lake in the middle of the Egyptian desert at all?","a":"Because the Nile reaches it. The rock wall between the valley and the depression has broken down, and the Bahr Yusuf, a second channel some 320 kilometres long leaving the river near Asyut, runs water into the basin."},{"q":"Why did Herodotus think Lake Moeris had been dug by hand?","a":"Because the country around it is so dry that the water plainly did not belong there, and it arrived by a channel from the Nile that ran in for six months and out for six — an arrangement that looks made rather than found."},{"q":"Why does the Faiyum evidence complicate the idea of farming arriving in Egypt?","a":"Because the domesticates do not displace anything. Plants and animals appear from about 5400 BCE, yet at Kom K and Kom W between 4850 and 4250 BCE fish still dominate the bones, continuing the pattern of the earlier Holocene occupation."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/The_leaf-shaped_Faiyum_Oasis_fed_by_a_channel_of_the_River_Nile_%28iss073e0178560%29.jpg/1920px-The_leaf-shaped_Faiyum_Oasis_fed_by_a_channel_of_the_River_Nile_%28iss073e0178560%29.jpg","title":"The Faiyum beside the valley","desc":"The depression and its lake, Birket el-Qarun, seen from orbit, joined to the dark strip of the Nile valley by cultivated land at the right.","credit":"NASA Johnson Space Center, Public domain, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:The_leaf-shaped_Faiyum_Oasis_fed_by_a_channel_of_the_River_Nile_(iss073e0178560).jpg","alt":"An oblique view from orbit of a leaf-shaped patch of dark cultivated ground holding two dark lakes, set in pale desert beside a long dark river strip."}},
    "eg-007": {"abstract":"The <b>Western Desert</b> is the part of the Sahara lying west of the Nile, and it is much the larger of the two deserts Egypt is set between.<sup class=\"fn\" data-fn=\"1\"></sup> Breasted described it as illimitable desolate hills of sand, gravel and rock standing 200 to 300 metres (650 to 1,000 feet) above the river, an otherwise waterless expanse broken only by an irregular line of oases running roughly parallel with the valley.<sup class=\"fn\" data-fn=\"1\"></sup> Apart from those depressions it offered the early people of the valley no economic resources at all, which is why Egypt faced its own river rather than the country on either side of it.<sup class=\"fn\" data-fn=\"1\"></sup> Herodotus knew the chain as a ridge of sand running from Thebes of Egypt to the Pillars of Heracles, with hills of salt about ten days' journey apart, a spring of cold sweet water on each and people living around it.<sup class=\"fn\" data-fn=\"2\"></sup> Strabo drew the conclusion for the country as a whole, writing that Egypt consists of only the river-land on either side of the Nile.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> It has not always been like this, and during the African humid period a northward shift of the monsoon rain belt gave the Sahara grassland, rivers and lakes.<sup class=\"fn\" data-fn=\"4\"></sup> How far north the rain reached is genuinely disputed: one reconstruction puts the belt near 31 degrees, with rainfall around 640 millimetres (25 inches) a year, about ten times what falls now.<sup class=\"fn\" data-fn=\"4\"></sup> Records of wind-blown dust reaching the Red Sea give a narrower answer, with fluxes falling by at least half during the humid period but wetter conditions extending only to about 22 degrees north, which tells against heavy plant cover over the northern Sahara.<sup class=\"fn\" data-fn=\"5\"></sup> Either way the desert returned, and satellite and station records show the Sahara still expanding across the twentieth century, seasonally and in its annual mean extent.<sup class=\"fn\" data-fn=\"6\"></sup> What is left is a desert that shielded Egypt's western flank without ever being quite empty, since people went on living at the oases strung along it.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 5–6, https://archive.org/details/historyofegyptfr00brea. [Open access]","Herodotus, <i>The Histories</i> 4.181, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D4%3Achapter%3D181. [Open access]","Strabo, <i>Geography</i> 17.1.4, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A1*.html. [Open access]","Jessica E. Tierney, Francesco S. R. Pausata and Peter B. deMenocal, “Rainfall Regimes of the Green Sahara,” <i>Science Advances</i> 3, no. 1 (2017): e1601503, https://doi.org/10.1126/sciadv.1601503. [Open access]","Daniel Palchan and Adi Torfstein, “A Drop in Sahara Dust Fluxes Records the Northern Limits of the African Humid Period,” <i>Nature Communications</i> 10 (2019): 3803, https://doi.org/10.1038/s41467-019-11701-z. [Open access]","Ye Liu and Yongkang Xue, “Expansion of the Sahara Desert and Shrinking of Frozen Land of the Arctic,” <i>Scientific Reports</i> 10 (2020): 4109, https://pmc.ncbi.nlm.nih.gov/articles/PMC7057959/. [Open access]"],"why":[{"q":"Why did Egypt turn towards its river rather than towards the land on either side of it?","a":"Because the land on either side had nothing to offer. The Western Desert is a waterless expanse of sand, gravel and rock broken only by a line of oases, and it held no economic resources for the early people of the valley."},{"q":"Why is the extent of the green Sahara still argued about?","a":"Because different evidence gives different answers. One reconstruction of rainfall puts the monsoon belt near 31 degrees north, while dust fluxes measured in Red Sea sediment suggest wetter conditions reached only about 22 degrees."},{"q":"Why were the oases inhabited when the desert around them was not?","a":"Because water reaches the surface in the depressions and nowhere else. Herodotus describes hills of salt about ten days' journey apart, each with a spring of cold sweet water, and people living around them."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/EgSandSea.jpg/1920px-EgSandSea.jpg","title":"Dunes of the Egyptian Sand Sea","desc":"Sand in the Western Desert, the kind of ground that covers most of Egypt's area and almost none of its inhabited land.","credit":"Roland Unger, CC BY-SA 3.0, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:EgSandSea.jpg","alt":"A broad expanse of smooth pale orange sand under a blue sky, with a low ridge of dunes along the horizon."}},
    "eg-008": {"abstract":"The <b>Eastern Desert</b> is the ground between the Nile and the Red Sea, and it is the less inhospitable of Egypt's two deserts, able to yield a scanty living to wandering people.<sup class=\"fn\" data-fn=\"1\"></sup> A range of granite mountains running parallel with the Red Sea coast carries gold-bearing quartz veins, with other gold-producing hills scattered between the river and the sea.<sup class=\"fn\" data-fn=\"1\"></sup> Deposits of alabaster and large masses of fine hard igneous rock brought quarrying here as well, and since the Red Sea harbours could be reached only by crossing it, established routes were traced early.<sup class=\"fn\" data-fn=\"1\"></sup> The rock underneath is Precambrian basement belonging to the Arabian-Nubian Shield, whose wide range of lithologies is why it holds so many kinds of mineral deposit.<sup class=\"fn\" data-fn=\"3\"></sup> Egyptian mining there is among the earliest recorded anywhere, and a papyrus map made in the reign of Ramesses IV shows the gold mines and greywacke quarries of the Wadi Hammamat.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Those quarries lie three days' journey from the Nile, and Isesi was the first pharaoh to leave his name at them, though their stone had probably already supplied the vases of earlier kings.<sup class=\"fn\" data-fn=\"2\"></sup> Because the river comes closest to the Red Sea at that point, a caravan leaving Coptos by way of Hammamat could reach the coast in five days, which made it the convenient road towards Punt.<sup class=\"fn\" data-fn=\"2\"></sup> Strabo describes the same crossing in his own day as a waterless road with stations built for merchants travelling by camel, who had once gone only by night and steered by the stars, carrying their water with them.<sup class=\"fn\" data-fn=\"4\"></sup> By then they had dug watering places to a great depth and cut cisterns for what little rain there is, and the journey took six or seven days.<sup class=\"fn\" data-fn=\"4\"></sup> Sediment cores from the Red Sea record the desert from the other side, showing dust blown east off the Sahara falling by at least half during the African humid period.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 6, https://archive.org/details/historyofegyptfr00brea. [Open access]","James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 128, https://archive.org/details/historyofegyptfr00brea. [Open access]","Abdelmonem Eldougdoug, Maha Abdelazeem, Mohamed Gobashy, Mohamed Abdelwahed, Yasser Abd El-Rahman, Ahmed Abdelhalim and Said Said, “Exploring Gold Mineralization in Altered Ultramafic Rocks in South Abu Marawat, Eastern Desert, Egypt,” <i>Scientific Reports</i> 13 (2023): 7293, https://doi.org/10.1038/s41598-023-33947-w. [Open access]","Strabo, <i>Geography</i> 17.1.45, trans. Horace Leonard Jones, https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Strabo/17A3*.html. [Open access]","Daniel Palchan and Adi Torfstein, “A Drop in Sahara Dust Fluxes Records the Northern Limits of the African Humid Period,” <i>Nature Communications</i> 10 (2019): 3803, https://doi.org/10.1038/s41467-019-11701-z. [Open access]"],"why":[{"q":"Why did Egypt bother with a desert at all, when it had the valley?","a":"Because the valley has no stone or metal. The Eastern Desert held gold-bearing quartz in a granite range along the Red Sea, alabaster and masses of fine hard igneous rock, none of which the floodplain could supply."},{"q":"Why did the road to the Red Sea start at Coptos?","a":"Because that is where the river comes closest to the sea. A caravan leaving Coptos and passing the Wadi Hammamat quarries could be at the coast in five days, which made it the convenient route towards Punt."},{"q":"Why did camel merchants cross this desert by night?","a":"Because the road was waterless and they had to carry their own water, so travelling in the cool and steering by the stars was the only way to do it before wells were dug deep and cisterns cut for rain."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Wadi_Hammamat_96_2962.jpg/1920px-Wadi_Hammamat_96_2962.jpg","title":"A well in the Wadi Hammamat","desc":"The dry valley that carried the road from the Nile at Coptos to the Red Sea, past the quarries the Egyptians worked for hard stone.","credit":"Adam Bülow-Jacobsen, CC BY 4.0, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Wadi_Hammamat_96_2962.jpg","alt":"A black and white photograph of a low ruined stone wellhead on a sandy valley floor, with dark rocky hills rising behind it."}},
    "eg-009": {"abstract":"<b>Kharga Oasis</b> is the southernmost of the chain of depressions running through the Western Desert roughly parallel with the Nile, and the one classical writers called simply the Great Oasis.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Breasted described that chain as the only break in an otherwise waterless expanse of sand, gravel and rock stretching away west of the river.<sup class=\"fn\" data-fn=\"1\"></sup> Herodotus knew the arrangement from the other end, as a ridge of sand running from Thebes of Egypt to the Pillars of Heracles, with hills of salt about ten days' journey apart, each carrying a spring of cold sweet water and people living round it.<sup class=\"fn\" data-fn=\"3\"></sup> He also records the town at Oasis as seven days' march from Thebes across sandy desert, inhabited by Samians, and called in Greek the Islands of the Blest.<sup class=\"fn\" data-fn=\"2\"></sup> It was the last place a Persian army sent against the Ammonians was seen, and the Ammonians said that a violent south wind had buried the men in sand midway between the two.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The water under all of this is the Nubian Sandstone Aquifer System, the largest groundwater aquifer in the Sahara, covering about 2 million square kilometres (770,000 square miles).<sup class=\"fn\" data-fn=\"4\"></sup> Four countries share it, Egypt with 38 per cent, Libya with 34, Sudan with 17 and Chad with 11, and Egypt and Libya hold most of the water in it.<sup class=\"fn\" data-fn=\"4\"></sup> It is chiefly a fossil reservoir with a low rate of recharge, which is another way of saying that most of what is drawn from it fell as rain in wetter ages than this one.<sup class=\"fn\" data-fn=\"4\"></sup> Those ages are measurable, and during the African humid period the monsoon rain belt reached far into what is now desert, with rainfall in places around ten times the modern figure.<sup class=\"fn\" data-fn=\"5\"></sup> An oasis is therefore not an exception to the desert but a place where an older and wetter Sahara can still be reached through the rock.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>","sources":["James Henry Breasted, <i>A History of Egypt from the Earliest Times to the Persian Conquest</i> (New York: Charles Scribner's Sons, 1905), 5–6, https://archive.org/details/historyofegyptfr00brea. [Open access]","Herodotus, <i>The Histories</i> 3.26, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D3%3Achapter%3D26. [Open access]","Herodotus, <i>The Histories</i> 4.181, trans. A. D. Godley, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0126%3Abook%3D4%3Achapter%3D181. [Open access]","Ahmed Mohamed, Saad S. Alarifi and Ahmed Abdelrady, “Sedimentary Cover and Structural Trends Affecting the Groundwater Flow in the Nubian Sandstone Aquifer System: Inferences from Geophysical, Field and Geochemical Data,” <i>Frontiers in Earth Science</i> 11 (2023): 1173569, https://doi.org/10.3389/feart.2023.1173569. [Open access]","Jessica E. Tierney, Francesco S. R. Pausata and Peter B. deMenocal, “Rainfall Regimes of the Green Sahara,” <i>Science Advances</i> 3, no. 1 (2017): e1601503, https://doi.org/10.1126/sciadv.1601503. [Open access]"],"why":[{"q":"Why is there fresh water here and nowhere else in the desert?","a":"Because the depression cuts down far enough to reach the Nubian Sandstone Aquifer System, the largest groundwater body in the Sahara, which lies under about 2 million square kilometres of desert and reaches the surface where the ground is low."},{"q":"Why is the water called fossil?","a":"Because it is barely being replaced. The aquifer has a very low rate of present-day recharge, so most of what is pumped out of it fell as rain during wetter periods, such as the African humid period when the monsoon belt reached far north."},{"q":"Why did an army marching west from Thebes stop here?","a":"Because it is the first inhabited place on that road and the last water before the crossing. Herodotus puts it seven days' march from Thebes across sandy desert, and the Persian force sent on towards the Ammonians was never seen again."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Kharga_Oasis_by_Hanne_Siegmeier.jpg/1920px-Kharga_Oasis_by_Hanne_Siegmeier.jpg","title":"Palm groves at Kharga","desc":"Date palms and a ruined temple in the oasis, with the desert escarpment beyond. The water that keeps them alive comes up out of the sandstone below.","credit":"kairoinfo4u (Hanne Siegmeier), CC BY 2.0, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Kharga_Oasis_by_Hanne_Siegmeier.jpg","alt":"A dense green mass of date palms filling the middle distance, with low sandstone temple walls among them and a pale desert plateau behind."}},
    "eg-010": {"abstract":"The <b>African humid period</b> is the stretch of the late glacial and early Holocene when a strengthened monsoon carried rain into what is now the Sahara, and for Egypt it is the setting of everything that happened before the pharaohs.<sup class=\"fn\" data-fn=\"1\"></sup> Plant waxes in sea-floor mud off West Africa put rainfall at a median of about 640 millimetres (25 inches) a year, roughly ten times what that coast gets now, with the wet zone reaching 31 degrees north.<sup class=\"fn\" data-fn=\"1\"></sup> How far the rain actually reached over Egypt's own latitudes is the part still argued about, and sediment accumulation rates in Red Sea and Gulf of Aden cores tell a narrower story.<sup class=\"fn\" data-fn=\"2\"></sup> Dust blown east off the Sahara fell by at least half during the period, but on that reading conditions were wetter only as far north as about 22 degrees, which tells against heavy plant cover over the northern and north-eastern Sahara.<sup class=\"fn\" data-fn=\"2\"></sup> Whatever its northern limit, there was water enough for people, and the Faiyum was occupied from about 7350 BCE.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The delta records the wet phase as growth, with its accretion rates highest in the early and middle Holocene and falling away with the monsoon afterwards.<sup class=\"fn\" data-fn=\"4\"></sup> At Lake Mareotis, on the delta's north-western edge, Nile water dominated the lagoon between roughly 7,000 and 5,500 years ago.<sup class=\"fn\" data-fn=\"5\"></sup> Between about 5,500 and 2,800 years ago that lagoon shifted from Nile-fed to marine-dominated, which is the end of the humid period written into a single body of water.<sup class=\"fn\" data-fn=\"5\"></sup> The same drying is what pushed people together, since falling river flow exposed productive floodplain for settlement and irrigation at the very time the desert around it was emptying.<sup class=\"fn\" data-fn=\"4\"></sup> Egypt is in that sense a product of the humid period's ending, a country assembled along one river once the ground on either side of it had stopped supporting anybody.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Jessica E. Tierney, Francesco S. R. Pausata and Peter B. deMenocal, “Rainfall Regimes of the Green Sahara,” <i>Science Advances</i> 3, no. 1 (2017): e1601503, https://doi.org/10.1126/sciadv.1601503. [Open access]","Daniel Palchan and Adi Torfstein, “A Drop in Sahara Dust Fluxes Records the Northern Limits of the African Humid Period,” <i>Nature Communications</i> 10 (2019): 3803, https://doi.org/10.1038/s41467-019-11701-z. [Open access]","Veerle Linseele, Wim Van Neer, Sofie Thys, Rebecca Phillipps, René Cappers, Willeke Wendrich and Simon Holdaway, “New Archaeozoological Data from the Fayum ‘Neolithic’ with a Critical Assessment of the Evidence for Early Stock Keeping in Egypt,” <i>PLOS ONE</i> 9, no. 10 (2014): e108517, https://doi.org/10.1371/journal.pone.0108517. [Open access]","Nick Marriner, Clément Flaux, Christophe Morhange and Jean-Daniel Stanley, “Tracking Nile Delta Vulnerability to Holocene Change,” <i>PLOS ONE</i> 8, no. 7 (2013): e69195, https://doi.org/10.1371/journal.pone.0069195. [Open access]","Clément Flaux, Matthieu Giaime, Valérie Pichot, Nick Marriner, Mena el-Assal, Abel Guihou, Pierre Deschamps, Christelle Claude and Christophe Morhange, “The Late Holocene Record of Lake Mareotis, Nile Delta, Egypt,” <i>E&G Quaternary Science Journal</i> 70, no. 1 (2021): 93–104, https://doi.org/10.5194/egqsj-70-93-2021. [Open access]"],"why":[{"q":"Why is the northern edge of the green Sahara so important for Egypt in particular?","a":"Because Egypt sits at the latitudes in question. A rain belt reaching 31 degrees north would have watered most of the Western Desert, while a limit near 22 degrees leaves nearly all of it dry, and the two readings come from different evidence."},{"q":"Why can a single lagoon record the end of a continental climate phase?","a":"Because its water came from two competing sources. Lake Mareotis was dominated by Nile water between about 7,000 and 5,500 years ago, and as the humid period ended it shifted to a marine-dominated system over the following millennia."},{"q":"Why did the drying concentrate people rather than simply drive them away?","a":"Because it opened land as it closed land. Falling river flow exposed productive floodplain that could be settled and irrigated, at the same time as the desert on either side of the valley was emptying of people."}],"image":{"src":"https://upload.wikimedia.org/wikipedia/commons/1/18/Bestias11.JPG","title":"Rock paintings in the Gilf Kebir","desc":"Cattle, wild animals and human figures painted on a shelter wall in the Western Desert, in country that is now among the driest on earth.","credit":"Clemens Schmillen, CC BY-SA 3.0, via Wikimedia Commons. https://commons.wikimedia.org/wiki/File:Bestias11.JPG","alt":"A rock wall painted in dark red with rows of cattle and other animals, many small human figures with raised limbs, and stencilled handprints."}}
  };
  (window.CARD_EXTRA_IN = window.CARD_EXTRA_IN || []).push({ CARD_EXTRA: CARD_EXTRA });
})();
